<style>
    .access-shell,.workspace-shell{color:#17211b}.access-top,.access-card,.workspace-card{background:#fff;border:1px solid #dfe7e2;border-radius:8px}.access-muted{color:#66736c}.access-btn{display:inline-flex;align-items:center;gap:.4rem;border-radius:7px;border:1px solid #cfdad3;padding:.55rem .8rem;font-weight:700;font-size:.85rem}.access-btn-primary{background:#147d4f;border-color:#147d4f;color:white}.access-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:1rem}.access-input{border:1px solid #cfdad3;border-radius:7px;padding:.55rem .7rem;width:100%;font-size:.9rem}.access-chip{display:inline-flex;border-radius:999px;background:#edf7f1;color:#146c45;padding:.2rem .55rem;font-size:.75rem;font-weight:700}.access-table{width:100%;border-collapse:separate;border-spacing:0}.access-table th{font-size:.72rem;text-transform:uppercase;color:#66736c;text-align:left;background:#f7faf8}.access-table th,.access-table td{padding:.8rem;border-bottom:1px solid #e7eee9;vertical-align:top}.workspace-grid{display:grid;grid-template-columns:repeat(12,minmax(0,1fr));gap:1rem}.workspace-tile{grid-column:span min(var(--w,4),12);min-height:150px}.builder-board .workspace-tile{cursor:grab}.access-tabs{display:flex;gap:.5rem;flex-wrap:wrap}.access-tab{border:1px solid #dfe7e2;border-radius:999px;padding:.4rem .7rem;background:#fff;font-size:.8rem}.access-tab.active{background:#e8f6ee;color:#0f6b43;border-color:#99cdb1}.dashboard-builder-row{display:grid;grid-template-columns:minmax(220px,1fr) 150px 170px minmax(210px,1fr) 230px;gap:1rem;align-items:center;border:1px solid #dfe7e2;border-radius:8px;padding:1rem}.dashboard-builder-row label span,.permission-builder-row label span{display:block;font-size:.75rem;font-weight:800;color:#66736c;margin-bottom:.25rem}.dashboard-builder-checks{display:grid;grid-template-columns:1fr 1fr;gap:.35rem;font-size:.8rem;font-weight:700}.permission-builder-row{display:grid;grid-template-columns:minmax(240px,1.4fr) 120px 130px 130px 130px 180px;gap:.75rem;align-items:center;border:1px solid #edf1ee;border-radius:8px;padding:.75rem}.access-icon-btn,.access-widget-icon{width:2.35rem;height:2.35rem;border-radius:8px;display:grid;place-items:center;font-weight:900}.access-icon-btn{border:1px solid #9fb0a7;color:#53635b}.access-widget-icon{background:#ece9ff;color:#5b55e8}.hierarchy-levels{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:1rem}.hierarchy-levels section{border:1px solid #dfe7e2;border-radius:8px;padding:1rem;background:#fbfdfc}.hierarchy-levels h3{font-weight:800}.hierarchy-levels p{font-size:.8rem;color:#66736c}.hierarchy-person{border:1px solid #edf1ee;border-radius:7px;padding:.7rem;background:#fff}.hierarchy-person span,.hierarchy-person small{display:block;color:#66736c;font-size:.75rem}@media(max-width:1100px){.dashboard-builder-row,.permission-builder-row{grid-template-columns:1fr 1fr}.hierarchy-levels{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.workspace-grid{grid-template-columns:1fr}.workspace-tile{grid-column:span 1}.access-table{display:block;overflow-x:auto}.access-top{display:block!important}.dashboard-builder-row,.permission-builder-row{grid-template-columns:1fr}.hierarchy-levels{grid-template-columns:1fr}}
</style>
